<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\Html;$this->title='球员';?><h1>参赛球员</h1><form method="get" class="wc-filters"><input name="q" placeholder="搜索球员" value="<?= Html::encode(Yii::$app->request->get('q','')) ?>"><select name="team_id"><option value="">全部球队</option><?php foreach($teams as $t):?><option value="<?= $t->id ?>" <?= Yii::$app->request->get('team_id')==$t->id?'selected':'' ?>><?= Html::encode($t->name) ?></option><?php endforeach ?></select><button>筛选</button></form><table><tr><th>球员</th><th>国家队</th><th>位置</th></tr><?php foreach($players as $p):?><tr><td><?= Html::a(Html::encode($p->name),['view','id'=>$p->id]) ?></td><td><?= Html::encode($p->team->name) ?></td><td><?= Html::encode($p->position) ?></td></tr><?php endforeach ?></table><?= yii\widgets\LinkPager::widget(['pagination'=>$pages]) ?>